public static JsonFeature createCircle(String id, double centerLat, double centerLon, double radius) {
    final int n = 36;
    final double delta = 360.0 / n;
    Coordinate[] coordinates = IntStream.range(0, n + 1).mapToObj(i -> DIST_EARTH.projectCoordinate(centerLat, centerLon, radius, (i * delta) % 360)).map(p -> new Coordinate(p.lon, p.lat)).toArray(Coordinate[]::new);
    // PATH: Test should invoke the next GeometryFactory.createPolygon(...) [step in execution path]
    Polygon polygon = new GeometryFactory().createPolygon(coordinates);
    JsonFeature result = new JsonFeature();
    result.setId(id);
    result.setGeometry(polygon);
    return result;
}

