    } else {
        logger.info("Applying rules for the following countries: {}", countryRuleFactory.getCountryToRuleMap().keySet());
    }
    logger.info("start creating graph from " + osmFile);
    OSMReader reader = new OSMReader(baseGraph.getBaseGraph(), osmParsers, osmReaderConfig).setFile(_getOSMFile()).setAreaIndex(areaIndex).setElevationProvider(eleProvider).setCountryRuleFactory(countryRuleFactory);
    logger.info((("using " + getBaseGraphString()) + ", memory:") + getMemInfo());
    createBaseGraphAndProperties();
    try {
