    int adjNode = edge.getAdjNode();
    GHPoint center = new GHPoint(getLat(na, baseNode, adjNode), getLon(na, baseNode, adjNode));
    deque.addLast(baseNode);
    deque.addLast(adjNode);
    visited.add(baseNode);
    visited.add(adjNode);
