import org.locationtech.jts.geom.Coordinate;
import org.locationtech.jts.geom.Geometry;
import org.locationtech.jts.geom.GeometryFactory;
import org.locationtech.jts.geom.Polygon;
import org.locationtech.jts.triangulate.DelaunayTriangulationBuilder;
import org.locationtech.jts.triangulate.quadedge.QuadEdgeSubdivision;
import org.locationtech.jts.triangulate.quadedge.Vertex;

import java.util.ArrayList;
import java.util.Collection;
import java.util.function.ToDoubleFunction;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class JTSTriangulatortriangulate_VertexsetZFikaTest {

    @Test
    public void testTriangulate() {
        RouterConfig routerConfig = mock(RouterConfig.class);
        when(routerConfig.getMaxVisitedNodes()).thenReturn(300);

        JTSTriangulator jtsTriangulator = new JTSTriangulator(routerConfig);

        Snap snap = mock(Snap.class);
        QueryGraph queryGraph = mock(QueryGraph.class);
        ShortestPathTree shortestPathTree = mock(ShortestPathTree.class);
        ToDoubleFunction<ShortestPathTree.IsoLabel> fz = mock(ToDoubleFunction.class);

        NodeAccess nodeAccess = mock(NodeAccess.class);
        when(queryGraph.getNodeAccess()).thenReturn(nodeAccess);

        when(snap.getClosestNode()).thenReturn(1);
        when(nodeAccess.getLat(1)).thenReturn(49.0);
        when(nodeAccess.getLon(1)).thenReturn(11.0);
        when(fz.applyAsDouble(null)).thenReturn(100.0);

        ShortestPathTree.IsoLabel isoLabel = new ShortestPathTree.IsoLabel();
        isoLabel.node = 1;
        isoLabel.parent = null;
        isoLabel.edge = 0;

        when(shortestPathTree.search(1, null)).thenAnswer(invocation -> {
            ShortestPathTree.SearchCallback callback = invocation.getArgument(1);
            callback.accept(isoLabel);
            return null;
        });

        jtsTriangulator.triangulate(snap, queryGraph, shortestPathTree, fz, 0.0);
    }
}

