        }
        numEdges++;
    } 
    LOGGER.debug(String.format(Locale.ROOT, "Finished building random graph" + ", nodes: %d, edges: %d , min distance: %.2f, max distance: %.2f
", graph.getNodes(), graph.getEdges(), minDist, maxDist));
