            indicesWithDifferentNodes.add(i);
        }
    }
    if (indicesWithDifferentNodes.size() != 1) {
        return false;
    }
    int b = indicesWithDifferentNodes.get(0);
    int a = b - 1;
    int c = b + 1;
    assert shorterPath.get(a) == longerPath.get(a);
    assert shorterPath.get(b) != longerPath.get(b);
