    @Test
    public void testComparePathsTriggersIntArrayListConstructor() {
        // Create mock Path objects
        Path refPath = Mockito.mock(Path.class);
        Path path = Mockito.mock(Path.class);

        // Create mock Graph
        Graph mockGraph = Mockito.mock(Graph.class);

        // Create mock IntIndexedContainers that will trigger the target path
        IntIndexedContainer refNodes = Mockito.mock(IntIndexedContainer.class);
        IntIndexedContainer pathNodes = Mockito.mock(IntIndexedContainer.class);

        // Setup the mock behavior to reach the target method
        Mockito.when(refPath.getWeight()).thenReturn(100.0);
        Mockito.when(path.getWeight()).thenReturn(100.0);
        Mockito.when(refPath.getDistance()).thenReturn(1000.0);
        Mockito.when(path.getDistance()).thenReturn(1000.0);
        Mockito.when(refPath.getTime()).thenReturn(3600000L);
        Mockito.when(path.getTime()).thenReturn(3600000L);

        // Make calcNodes return different containers to enter the if block
        Mockito.when(refPath.calcNodes()).thenReturn(refNodes);
        Mockito.when(path.calcNodes()).thenReturn(pathNodes);

        // Make the containers not equal
        Mockito.when(refNodes.equals(pathNodes)).thenReturn(false);

        // Make both paths use the same graph
        Mockito.when(refPath.getGraph()).thenReturn(mockGraph);
        Mockito.when(path.getGraph()).thenReturn(mockGraph);

        // Setup container sizes to pass the size check in pathsEqualExceptOneEdge
        Mockito.when(refNodes.size()).thenReturn(3);
        Mockito.when(pathNodes.size()).thenReturn(4);

        // Setup the shorter/longer path logic
        Mockito.when(refNodes.get(Mockito.anyInt())).thenReturn(1);
        Mockito.when(pathNodes.get(Mockito.anyInt())).thenReturn(2);

        // Call the entry point method
        GHUtility.comparePaths(refPath, path, 0, 1, 12345L);
    }
}

