    int activeLandmarkCount = ghConfig.getInt(Landmark.ACTIVE_COUNT_DEFAULT, Math.min(8, lmPreparationHandler.getLandmarks()));
    if (activeLandmarkCount > lmPreparationHandler.getLandmarks()) {
        throw new IllegalArgumentException((("Default value for active landmarks " + activeLandmarkCount) + " should be less or equal to landmark count of ") + lmPreparationHandler.getLandmarks());
    }
    routerConfig.setActiveLandmarkCount(activeLandmarkCount);
    calcChecksums = ghConfig.getBool("graph.calc_checksums", false);
    return this;
