    if (!missing.isEmpty()) {
        String encodedValuesString = encodedValuesWithProps.entrySet().stream().map(e -> e.getKey() + (e.getValue().isEmpty() ? "" : "|" + e.getValue().toMap().entrySet().stream().map(p -> (p.getKey() + "=") + p.getValue()).collect(Collectors.joining("|")))).collect(Collectors.joining(", "));
