    osmReaderConfig.setWorkerThreads(ghConfig.getInt("datareader.worker_threads", osmReaderConfig.getWorkerThreads()));
    // index
    preciseIndexResolution = ghConfig.getInt("index.high_resolution", preciseIndexResolution);
