import com.graphhopper.reader.osm.SkipOptions;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.mock;

public class PbfBlobDecoderreadBlobContent_BlobhasZlibDataFikaTest {

    @Test
    public void testRunToHasZlibData() throws Exception {
        // Create mock listener
        PbfBlobDecoderListener listener = mock(PbfBlobDecoderListener.class);

        // Create SkipOptions that doesn't skip anything
        SkipOptions skipOptions = new SkipOptions();

        // Create raw blob data that will trigger hasZlibData() path
        // We need to create a valid protobuf blob with zlib data
        byte[] rawBlob = createZlibBlob();

        // Create instance with OSMHeader blob type to go through processOsmHeader path
        PbfBlobDecoder decoder = new PbfBlobDecoder(
            "OSMHeader",
            rawBlob,
            listener,
            skipOptions
        );

        // Execute the entry point method
        decoder.run();
    }

    private byte[] createZlibBlob() {
        // Create a minimal valid Blob protobuf with zlib data
        // This will cause Fileformat.Blob.parseFrom() to succeed
        // and blob.hasZlibData() to return true
        org.openstreetmap.osmosis.osmbinary.Fileformat.Blob.Builder blobBuilder = 
            org.openstreetmap.osmosis.osmbinary.Fileformat.Blob.newBuilder();

        // Set raw size
        blobBuilder.setRawSize(10);

        // Create minimal zlib compressed data (just a few bytes)
        byte[] zlibData = new byte[] {120, -100, 99, 96, 0, 0, 0, 4, 0, 1};

        // Set zlib data
        blobBuilder.setZlibData(com.google.protobuf.ByteString.copyFrom(zlibData));

        // Build and serialize to byte array
        org.openstreetmap.osmosis.osmbinary.Fileformat.Blob blob = blobBuilder.build();
        return blob.toByteArray();
    }
}

