        }
        if (CustomWeighting.NAME.equals(profile.getWeighting()) && (profile.getCustomModel() == null))
            throw new IllegalArgumentException(("custom model for profile '" + profile.getName()) + "' was empty");

        if ((!CustomWeighting.NAME.equals(profile.getWeighting())) && (profile.getCustomModel() != null))
