                    artificialEdgesByEdge.getOrDefault(restriction.getToEdge(), EMPTY_SET).forEach(((IntProcedure) (toEdge -> restrictTurn(turnRestrictionEnc, viaEdge, node, toEdge))));
                }
            }
        }
    }
