        String[] strs = alpha2WithSubdivision.split("-");
        if ((strs.length == 0) || (strs.length > 2))
            throw new IllegalStateException("Invalid alpha2: " + alpha2WithSubdivision);

        Country c = Country.find(strs[0]);
        if (c == null)
