public void readGraph() throws IOException {
    if (osmParsers == null)
        throw new IllegalStateException("Tag parsers were not set.");

    if (osmFile == null)
        throw new IllegalStateException("No OSM file specified");

    if (!osmFile.exists())
        throw new IllegalStateException("Your specified OSM file does not exist:" + osmFile.getAbsolutePath());

    if (!baseGraph.isInitialized())
        throw new IllegalStateException("BaseGraph must be initialize before we can read OSM");

    WaySegmentParser waySegmentParser = new WaySegmentParser.Builder(baseGraph.getNodeAccess(), baseGraph.getDirectory()).setElevationProvider(this::getElevation).setWayFilter(this::acceptWay).setSplitNodeFilter(this::isBarrierNode).setWayPreprocessor(this::preprocessWay).setRelationPreprocessor(this::preprocessRelations).setRelationProcessor(this::processRelation).setEdgeHandler(this::addEdge).setWorkerThreads(config.getWorkerThreads()).build();
    waySegmentParser.readOSM(osmFile);
    osmDataDate = waySegmentParser.getTimestamp();
    if (baseGraph.getNodes() == 0)
        throw new RuntimeException("Graph after reading OSM must not be empty");

    releaseEverythingExceptRestrictionData();
    addRestrictionsToGraph();
    releaseRestrictionData();
    LOGGER.info("Finished reading OSM file: {}, nodes: {}, edges: {}, zero distance edges: {}", osmFile.getAbsolutePath(), nf(baseGraph.getNodes()), nf(baseGraph.getEdges()), nf(zeroCounter));
}

