import java.util.*;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

public class LandmarkStorage_LandmarkExplorersetSubnetworks_IntObjectMapforEachFikaTest {

    @Test
    public void testCreateLandmarksTriggersIntObjectMapForEach() {
        // Mock required constructor dependencies
        BaseGraph mockGraph = Mockito.mock(BaseGraph.class);
        EncodedValueLookup mockEncodedValueLookup = Mockito.mock(EncodedValueLookup.class);
        Directory mockDir = Mockito.mock(Directory.class);
        LMConfig mockLmConfig = Mockito.mock(LMConfig.class);
        Weighting mockWeighting = Mockito.mock(Weighting.class);
        DataAccess mockDataAccess = Mockito.mock(DataAccess.class);
        BooleanEncodedValue mockBooleanEncodedValue = Mockito.mock(BooleanEncodedValue.class);
        NodeAccess mockNodeAccess = Mockito.mock(NodeAccess.class);

        // Configure mocks for constructor
        when(mockGraph.getNodes()).thenReturn(10);
        when(mockGraph.getNodeAccess()).thenReturn(mockNodeAccess);
        when(mockLmConfig.getName()).thenReturn("test");
        when(mockLmConfig.getWeighting()).thenReturn(mockWeighting);
        when(mockWeighting.hasTurnCosts()).thenReturn(false);
        when(mockWeighting.calcEdgeWeight(any(), any())).thenReturn(1.0);
        when(mockDir.create(any())).thenReturn(mockDataAccess);

        // Configure mocks for createLandmarks execution
        when(mockEncodedValueLookup.hasEncodedValue("subnetwork_test")).thenReturn(true);
        when(mockEncodedValueLookup.getBooleanEncodedValue("subnetwork_test")).thenReturn(mockBooleanEncodedValue);

        // Create instance using the provided constructor
        LandmarkStorage storage = new LandmarkStorage(mockGraph, mockEncodedValueLookup, mockDir, mockLmConfig, 2);

        // Configure instance to reach the target method
        storage.setMinimumNodes(1); // Ensure subnetworks are processed
        storage.setLogDetails(false); // Disable logging

        // Mock TarjanSCC to return a small subnetwork
        TarjanSCC.ConnectedComponents mockComponents = Mockito.mock(TarjanSCC.ConnectedComponents.class);
        IntArrayList subnetwork = new IntArrayList();
        subnetwork.add(0); // Single node subnetwork
        List<IntArrayList> componentsList = Collections.singletonList(subnetwork);
        when(mockComponents.getComponents()).thenReturn(componentsList);

        // Use reflection to set factor to avoid estimation
        try {
            java.lang.reflect.Field factorField = LandmarkStorage.class.getDeclaredField("factor");
            factorField.setAccessible(true);
            factorField.set(storage, 1.0);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Mock static TarjanSCC.findComponents method using Mockito's static mock
        try (var mockedTarjan = Mockito.mockStatic(TarjanSCC.class)) {
            mockedTarjan.when(() -> TarjanSCC.findComponents(any(), any(), any()))
                    .thenReturn(mockComponents);

            // Execute entry point
            storage.createLandmarks();
        }
    }
}

