    map.forEach(new IntObjectPredicate<SPTEntry>() {
        @Override
        public boolean apply(int nodeId, SPTEntry value) {
            int sn = subnetworks[nodeId];
            if (sn != subnetworkId) {
                if ((sn != UNSET_SUBNETWORK) && (sn != UNCLEAR_SUBNETWORK)) {
