    this.LM_ROW_LENGTH = landmarks * 4;
    this.FROM_OFFSET = 0;
    this.TO_OFFSET = 2;
    this.landmarkIDs = new ArrayList<>();
    this.subnetworkStorage = new SubnetworkStorage(dir.create("landmarks_subnetwork_" + lmConfig.getName()));
}

