        ensureWriteAccess();
        importOSM();
        postImportOSM();
        cleanUp();
        properties.put("profiles", getProfilesString());
        writeEncodingManagerToProperties();
        postProcessing(closeEarly);
        flush();
    } finally {
        if (lock != null)
            lock.release();

