    properties.put("datareader.import.date", f.format(new Date()));
    if (reader.getDataDate() != null) {
        properties.put("datareader.data.date", f.format(reader.getDataDate()));
    }
}

private List<CustomArea> readCustomAreas() // PATH: Test should invoke the next ObjectMapper.registerModule(...) [step in execution path]
{
    ObjectMapper objectMapper = new ObjectMapper();
    objectMapper.registerModule(new JtsModule());
    final Path bordersDirectory = Paths.get(customAreasDirectory);
    List<JsonFeatureCollection> jsonFeatureCollections = new ArrayList<>();
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(bordersDirectory, "*.{geojson,json}")) {
        for (Path borderFile : stream) {
            try (BufferedReader reader = Files.newBufferedReader(borderFile, StandardCharsets.UTF_8)) {
                JsonFeatureCollection jsonFeatureCollection = objectMapper.readValue(reader, JsonFeatureCollection.class);
                jsonFeatureCollections.add(jsonFeatureCollection);
            }
        }
    } catch (IOException e) {
        throw new UncheckedIOException(e);
    }
    return jsonFeatureCollections.stream().flatMap(j -> j.getFeatures().stream()).map(CustomArea::fromJsonFeature).collect(Collectors.toList());
}
