public void close() {
    if (baseGraph != null)
        baseGraph.close();

    if (properties != null)
        properties.close();

    chGraphs.values().forEach(RoutingCHGraph::close);
    landmarks.values().forEach(LandmarkStorage::close);
    if (locationIndex != null)
