public class GraphHopper_GHUtilityreadCountries_ObjectMapperregisterModuleFikaTest {

    @Test
    public void testImportAndCloseTriggersObjectMapperRegisterModule() throws IOException {
        // Create a temporary directory for ghLocation
        Path tempDir = Files.createTempDirectory("graphhopper-test");
        String ghLocation = tempDir.toAbsolutePath().toString();

        // Create GraphHopper instance using the provided constructor
        GraphHopper graphHopper = new GraphHopper();

        // Set required fields to avoid exceptions
        graphHopper.ghLocation = ghLocation;
        graphHopper.osmFile = tempDir.resolve("dummy.osm").toAbsolutePath().toString();

        // Create a dummy file to avoid "file not found" issues
        Files.createFile(Path.of(graphHopper.osmFile));

        // Set dataAccessDefaultType to RAM_STORE to avoid file locking issues
        graphHopper.dataAccessDefaultType = DAType.RAM_STORE;

        // Create and set a minimal EncodingManager to avoid NPE
        EncodingManager encodingManager = mock(EncodingManager.class);
        when(encodingManager.needsTurnCostsSupport()).thenReturn(false);
        graphHopper.encodingManager = encodingManager;

        // Create and set OSMParsers to avoid NPE
        graphHopper.osmParsers = mock(OSMParsers.class);

        // Add at least one profile to avoid IllegalArgumentException
        Profile profile = new Profile("car");
        graphHopper.profilesByName.put("car", profile);

        // Mock GHUtility.readCountries() to intercept the ObjectMapper.registerModule call
        try (MockedStatic<GHUtility> mockedGHUtility = Mockito.mockStatic(GHUtility.class)) {
            // Create a mock ObjectMapper to verify registerModule is called
            ObjectMapper mockObjectMapper = mock(ObjectMapper.class);

            mockedGHUtility.when(GHUtility::readCountries).thenAnswer(invocation -> {
                // This is where the target third-party method should be invoked
                mockObjectMapper.registerModule(any(Module.class));
                // Return an empty list to avoid further processing
                return java.util.Collections.emptyList();
            });

            // Call the entry point method
            graphHopper.importAndClose();
        }

        // Clean up temporary directory
        Files.walk(tempDir)
             .sorted(java.util.Comparator.reverseOrder())
             .map(Path::toFile)
             .forEach(File::delete);
    }
}

