protected void process(boolean closeEarly) {
    prepareImport();
    if (encodingManager == null) {
        throw new IllegalStateException("The EncodingManager must be created in `prepareImport()`");
    }
    GHDirectory directory = new GHDirectory(ghLocation, dataAccessDefaultType);
    directory.configure(dataAccessConfig);
    baseGraph = new BaseGraph.Builder(getEncodingManager()).setDir(directory).set3D(hasElevation()).withTurnCosts(encodingManager.needsTurnCostsSupport()).setSegmentSize(defaultSegmentSize).build();
    properties = new StorableProperties(directory);
    checkProfilesConsistency();
    GHLock lock = null;
    try // PATH: Test should invoke the next GraphHopper.importOSM(...) [step in execution path]
    {
        if (directory.getDefaultType().isStoring()) {
            lockFactory.setLockDir(new File(ghLocation));
            lock = lockFactory.create(fileLockName, true);
            if (!lock.tryLock()) {
                throw new RuntimeException("To avoid multiple writers we need to obtain a write lock but it failed. In " + ghLocation, lock.getObtainFailedReason());
            }
        }
        ensureWriteAccess();
        importOSM();
        postImportOSM();
        cleanUp();
        properties.put("profiles", getProfilesString());
        writeEncodingManagerToProperties();
        postProcessing(closeEarly);
        flush();
    } finally {
        if (lock != null) {
            lock.release();
        }
    }
}

protected void importOSM() {
    if (osmFile == null) {
        throw new IllegalStateException(("Couldn't load from existing folder: " + ghLocation) + " but also cannot use file for DataReader as it wasn't specified!");
    }
    // PATH: Test should invoke the next GHUtility.readCountries(...) [step in execution path]
    List<CustomArea> customAreas = readCountries();
    if (isEmpty(customAreasDirectory)) {
