protected void postProcessing(boolean closeEarly) {
    calcChecksums();
    initLocationIndex();
    importPublicTransit();
    if (closeEarly) {
        boolean includesCustomProfiles = profilesByName.values().stream().anyMatch(p -> CustomWeighting.NAME.equals(p.getWeighting()));
