        if (factor <= 0) {
            throw new IllegalStateException((((((("factor wasn't initialized " + factor) + ", subnetworks:") + graphComponents.getComponents().size()) + ", minimumNodes:") + minimumNodes) + ", current size:") + subnetworkIds.size());
