        return new CustomWeighting.Parameters(prio::getSpeed, prio::calcMaxSpeed, prio::getPriority, prio::calcMaxPriority, prio::getTurnPenalty, customModel.getDistanceInfluence() == null ? 0 : customModel.getDistanceInfluence(), customModel.getHeadingPenalty() == null ? Parameters.Routing.DEFAULT_HEADING_PENALTY : customModel.getHeadingPenalty());
