public void readGraph() throws IOException // PATH: Test should invoke the next OSMReader.addRestrictionsToGraph(...) [step in execution path]
{
    if (osmParsers == null) {
        throw new IllegalStateException("Tag parsers were not set.");
    }
    if (osmFile == null) {
        throw new IllegalStateException("No OSM file specified");
    }
    if (!osmFile.exists()) {
        throw new IllegalStateException("Your specified OSM file does not exist:" + osmFile.getAbsolutePath());
    }
    if (!baseGraph.isInitialized()) {
        throw new IllegalStateException("BaseGraph must be initialize before we can read OSM");
    }
    WaySegmentParser waySegmentParser = new WaySegmentParser.Builder(baseGraph.getNodeAccess(), baseGraph.getDirectory()).setElevationProvider(this::getElevation).setWayFilter(this::acceptWay).setSplitNodeFilter(this::isBarrierNode).setWayPreprocessor(this::preprocessWay).setRelationPreprocessor(this::preprocessRelations).setRelationProcessor(this::processRelation).setEdgeHandler(this::addEdge).setWorkerThreads(config.getWorkerThreads()).build();
    waySegmentParser.readOSM(osmFile);
    osmDataDate = waySegmentParser.getTimestamp();
    if (baseGraph.getNodes() == 0) {
        throw new RuntimeException("Graph after reading OSM must not be empty");
    }
    releaseEverythingExceptRestrictionData();
    addRestrictionsToGraph();
    releaseRestrictionData();
    LOGGER.info("Finished reading OSM file: {}, nodes: {}, edges: {}, zero distance edges: {}", osmFile.getAbsolutePath(), nf(baseGraph.getNodes()), nf(baseGraph.getEdges()), nf(zeroCounter));
}

private void addRestrictionsToGraph() // PATH: Test should invoke the next RestrictionSetter.setRestrictions(...) [step in execution path]
{
    if (turnCostStorage == null) {
        return;
    }
    StopWatch sw = StopWatch.started();
    // The OSM restriction format is explained here: https://wiki.openstreetmap.org/wiki/Relation:restriction
    List<Triple<ReaderRelation, RestrictionTopology, RestrictionMembers>> restrictionRelationsWithTopology = new ArrayList<>(restrictionRelations.size());
    for (ReaderRelation restrictionRelation : restrictionRelations) {
        try {
            // Build the topology of the OSM relation in the graph representation. This only needs to be done once for all
            // vehicle types (we also want to print warnings only once)
            restrictionRelationsWithTopology.add(OSMRestrictionConverter.buildRestrictionTopologyForGraph(baseGraph, restrictionRelation, restrictedWaysToEdgesMap::getEdges));
        } catch (OSMRestrictionException e) {
            warnOfRestriction(restrictionRelation, e);
        }
    }
    // It is important to set the restrictions for all parsers/encoded values at once to make
    // sure the resulting turn restrictions do not interfere.
    List<RestrictionSetter.Restriction> restrictions = new ArrayList<>();
    // For every restriction we set flags that indicate the validity for the different parsers
    List<BitSet> encBits = new ArrayList<>();
    for (Triple<ReaderRelation, RestrictionTopology, RestrictionMembers> r : restrictionRelationsWithTopology) {
        try {
            BitSet bits = new BitSet(osmParsers.getRestrictionTagParsers().size());
            RestrictionType restrictionType = null;
            for (int i = 0; i < osmParsers.getRestrictionTagParsers().size(); i++) {
                RestrictionTagParser restrictionTagParser = osmParsers.getRestrictionTagParsers().get(i);
                RestrictionTagParser.Result res = restrictionTagParser.parseRestrictionTags(r.first.getTags());
                // this relation is ignored by this restriction tag parser
                if (res == null) {
                    continue;
                }
                OSMRestrictionConverter.checkIfTopologyIsCompatibleWithRestriction(r.second, res.getRestriction());
                // so far we restrict ourselves to restriction relations that use the same type for all vehicles
                if ((restrictionType != null) && (res.getRestrictionType() != restrictionType)) {
                    throw new OSMRestrictionException("has different restriction type for different vehicles.");
                }
                restrictionType = res.getRestrictionType();
                bits.set(i);
            }
            if (bits.cardinality() > 0) {
                List<RestrictionSetter.Restriction> tmpRestrictions = OSMRestrictionConverter.buildRestrictionsForOSMRestriction(baseGraph, r.second, restrictionType);
                restrictions.addAll(tmpRestrictions);
                tmpRestrictions.forEach(__ -> encBits.add(RestrictionSetter.copyEncBits(bits)));
            }
        } catch (OSMRestrictionException e) {
            warnOfRestriction(r.first, e);
        }
    }
    restrictionSetter.setRestrictions(restrictions, encBits);
    LOGGER.info("Finished adding turn restrictions. total turn cost entries: {}, took: {}", Helper.nf(baseGraph.getTurnCostStorage().getTurnCostsCount()), sw.stop().getTimeString());
}

public void setRestrictions(List<Restriction> restrictions, List<BitSet> encBits) {
    if (restrictions.size() != encBits.size()) {
        throw new IllegalArgumentException((("There must be as many encBits as restrictions. Got: " + encBits.size()) + " and ") + restrictions.size());
    }
    List<InternalRestriction> internalRestrictions = restrictions.stream().map(this::convertToInternal).toList();
    disableRedundantRestrictions(internalRestrictions, encBits);
    LongIntMap artificialEdgeKeysByIncViaPairs = new LongIntScatterMap();
    IntObjectMap<IntSet> artificialEdgesByEdge = new IntObjectScatterMap<>();
    for (int i = 0; i < internalRestrictions.size(); i++) {
        if (encBits.get(i).cardinality() < 1) {
            continue;
        }
        InternalRestriction restriction = internalRestrictions.get(i);
        if (restriction.getEdgeKeys().size() < 3) {
            continue;
        }
        // PATH: Test should invoke the next RestrictionSetter$InternalRestriction.getFromEdge(...) [step in execution path]
        int incomingEdge = restriction.getFromEdge();
        for (int j = 1; j < (restriction.getEdgeKeys().size() - 1); ++j) {
            int viaEdgeKey = restriction.getEdgeKeys().get(j);
            long key = BitUtil.LITTLE.toLong(incomingEdge, viaEdgeKey);
            int artificialEdgeKey;
            if (artificialEdgeKeysByIncViaPairs.containsKey(key)) {
                artificialEdgeKey = artificialEdgeKeysByIncViaPairs.get(key);
            } else {
                int viaEdge = GHUtility.getEdgeFromEdgeKey(viaEdgeKey);
                EdgeIteratorState artificialEdgeState = baseGraph.copyEdge(viaEdge, true);
                int artificialEdge = artificialEdgeState.getEdge();
                if (artificialEdgesByEdge.containsKey(viaEdge)) {
                    IntSet artificialEdges = artificialEdgesByEdge.get(viaEdge);
                    artificialEdges.forEach(((IntProcedure) (a -> {
                        for (BooleanEncodedValue turnRestrictionEnc : turnRestrictionEncs) {
                            restrictTurnsBetweenEdges(turnRestrictionEnc, artificialEdgeState, a);
                        }
                    })));
                    artificialEdges.add(artificialEdge);
                } else {
                    IntSet artificialEdges = new IntScatterSet();
                    artificialEdges.add(artificialEdge);
                    artificialEdgesByEdge.put(viaEdge, artificialEdges);
                }
                for (BooleanEncodedValue turnRestrictionEnc : turnRestrictionEncs) {
                    restrictTurnsBetweenEdges(turnRestrictionEnc, artificialEdgeState, viaEdge);
                }
                artificialEdgeKey = artificialEdgeState.getEdgeKey();
                if (baseGraph.getEdgeIteratorStateForKey(viaEdgeKey).get(REVERSE_STATE)) {
                    artificialEdgeKey = GHUtility.reverseEdgeKey(artificialEdgeKey);
                }
                artificialEdgeKeysByIncViaPairs.put(key, artificialEdgeKey);
            }
            restriction.actualEdgeKeys.set(j, artificialEdgeKey);
            incomingEdge = GHUtility.getEdgeFromEdgeKey(artificialEdgeKey);
        }
    }
    artificialEdgeKeysByIncViaPairs.forEach(((LongIntProcedure) ((incViaPair, artificialEdgeKey) -> {
        int incomingEdge = BitUtil.LITTLE.getIntLow(incViaPair);
        int viaEdgeKey = BitUtil.LITTLE.getIntHigh(incViaPair);
        int viaEdge = GHUtility.getEdgeFromEdgeKey(viaEdgeKey);
        int node = baseGraph.getEdgeIteratorStateForKey(viaEdgeKey).getBaseNode();
        // we restrict turning onto the original edge and all artificial edges except the one we created for this in-edge
        // i.e. we force turning onto the artificial edge we created for this in-edge
        for (BooleanEncodedValue turnRestrictionEnc : turnRestrictionEncs) {
            restrictTurn(turnRestrictionEnc, incomingEdge, node, viaEdge);
        }
        IntSet artificialEdges = artificialEdgesByEdge.get(viaEdge);
        artificialEdges.forEach(((IntProcedure) (a -> {
            if (a != GHUtility.getEdgeFromEdgeKey(artificialEdgeKey)) {
                for (BooleanEncodedValue turnRestrictionEnc : turnRestrictionEncs) {
                    restrictTurn(turnRestrictionEnc, incomingEdge, node, a);
                }
            }
        })));
    })));
    for (int i = 0; i < internalRestrictions.size(); i++) {
        if (encBits.get(i).cardinality() < 1) {
            continue;
        }
        InternalRestriction restriction = internalRestrictions.get(i);
        if (restriction.getEdgeKeys().size() < 3) {
            IntSet fromEdges = artificialEdgesByEdge.getOrDefault(restriction.getFromEdge(), new IntScatterSet());
            fromEdges.add(restriction.getFromEdge());
            IntSet toEdges = artificialEdgesByEdge.getOrDefault(restriction.getToEdge(), new IntScatterSet());
            toEdges.add(restriction.getToEdge());
            for (int j = 0; j < turnRestrictionEncs.size(); j++) {
                BooleanEncodedValue turnRestrictionEnc = turnRestrictionEncs.get(j);
                if (encBits.get(i).get(j)) {
                    fromEdges.forEach(((IntProcedure) (from -> toEdges.forEach(((IntProcedure) (to -> {
                        restrictTurn(turnRestrictionEnc, from, restriction.getViaNodes().get(0), to);
                    }))))));
                }
            }
        } else {
            int viaEdgeKey = restriction.getActualEdgeKeys().get(restriction.getActualEdgeKeys().size() - 2);
            int viaEdge = GHUtility.getEdgeFromEdgeKey(viaEdgeKey);
            int node = baseGraph.getEdgeIteratorStateForKey(viaEdgeKey).getAdjNode();
            // For via-edge restrictions we deny turning from the from-edge onto the via-edge,
            // but allow turning onto the artificial edge(s) instead (see above). Then we deny
            // turning from the artificial edge onto the to-edge here.
            for (int j = 0; j < turnRestrictionEncs.size(); j++) {
                BooleanEncodedValue turnRestrictionEnc = turnRestrictionEncs.get(j);
                if (encBits.get(i).get(j)) {
                    restrictTurn(turnRestrictionEnc, viaEdge, node, restriction.getToEdge());
                    // also restrict the turns to the artificial edges corresponding to the to-edge
                    artificialEdgesByEdge.getOrDefault(restriction.getToEdge(), EMPTY_SET).forEach(((IntProcedure) (toEdge -> restrictTurn(turnRestrictionEnc, viaEdge, node, toEdge))));
                }
            }
        }
    }
}

