        findComponentForEdgeKey(q, adj);
        edgeKeyLowLink.minTo(p, edgeKeyLowLink.get(q));
    } else if (edgeKeyOnStack.contains(q)) {
        edgeKeyLowLink.minTo(p, edgeKeyIndex.get(q));
    }
}

