    if (graph.getEdges() != prepareGraph.getOriginalEdges()) {
        throw new IllegalArgumentException((("Cannot initialize from given graph. The number of edges does not match: " + graph.getEdges()) + " vs. ") + prepareGraph.getOriginalEdges());
