    nodeContractor.initFromGraph();
}

private void logFinalGraphStats() {
    logger.info("shortcut weights - under minimum: {}, over maximum: {}, minimum valid: {}, maximum valid: {}", Helper.nf(chStore.getNumShortcutsUnderMinWeight()), Helper.nf(chStore.getNumShortcutsOverMaxWeight()), chStore.getMinValidWeight(), chStore.getMaxValidWeight());
    logger.info("took: {}s, graph now - num edges: {}, num nodes: {}, num shortcuts: {}", ((int) (allSW.getSeconds())), nf(graph.getEdges()), nf(nodes), nf(chStore.getShortcuts()));
}

private void logFixedNodeOrderingStats(int nodesContracted, int logSize, StopWatch stopWatch) {
    logger.info(String.format(Locale.ROOT, "nodes: %10s / %10s (%6.2f%%), shortcuts: %10s, speed = %6.2f nodes/ms, %s, %s", nf(nodesContracted), nf(nodes), (100.0 * nodesContracted) / nodes, nf(nodeContractor.getAddedShortcutsCount()), nodesContracted == 0 ? 0 : logSize / ((double) (stopWatch.getMillis())), nodeContractor.getStatisticsString(), Helper.getMemInfo()));
}

private void logHeuristicStats(int updateCounter) {
    logger.info(String.format(Locale.ROOT, "%s, nodes: %10s, shortcuts: %10s, updates: %2d, checked-nodes: %10s, %s, %s, %s", isEdgeBased() ? "edge" : "node", nf(sortedNodes.size()), nf(nodeContractor.getAddedShortcutsCount()), updateCounter, nf(checkCounter), getTimesAsString(), nodeContractor.getStatisticsString(), Helper.getMemInfo()));
}

private void setMaxLevelOnAllNodes() {
    chBuilder.setLevelForAllNodes(maxLevel);
}

private void updatePrioritiesOfRemainingNodes() {
    periodicUpdateSW.start();
    sortedNodes.clear();
    for (int node = 0; node < nodes; node++) {
        if (isContracted(node))
            continue;

        float priority = calculatePriority(node);
        sortedNodes.push(node, priority);
    }
    periodicUpdateSW.stop();
}

