        when(baseGraph.isFrozen()).thenReturn(true);
        when(baseGraph.getNodes()).thenReturn(2);
        when(baseGraph.getEdges()).thenReturn(1);
        when(baseGraph.getBaseGraph()).thenReturn(baseGraph);
