        when(chStorage.getNumShortcutsOverMaxWeight()).thenReturn(0);
        when(chStorage.getMinValidWeight()).thenReturn(0.0);
        when(chStorage.getMaxValidWeight()).thenReturn(0.0);

        // Mock CHStorage.fromGraph to return our mock
        try (var mockedStatic = Mockito.mockStatic(CHStorage.class)) {
            mockedStatic.when(() -> CHStorage.fromGraph(baseGraph, chConfig)).thenReturn(chStorage);

            // Create instance using the private constructor via reflection
