public static Result calcPaths(List<GHPoint> points, QueryGraph queryGraph, List<Snap> snaps, DirectedEdgeFilter directedEdgeFilter, PathCalculator pathCalculator, List<String> curbsides, String curbsideStrictness, List<Double> headings, boolean passThrough) {
    if ((!curbsides.isEmpty()) && (curbsides.size() != points.size())) {
        throw new IllegalArgumentException(("If you pass " + CURBSIDE) + ", you need to pass exactly one curbside for every point, empty curbsides will be ignored");
    }
    if ((!curbsides.isEmpty()) && (!headings.isEmpty())) {
        throw new IllegalArgumentException("You cannot use curbsides and headings or pass_through at the same time");
    }
    final int legs = snaps.size() - 1;
    Result result = new Result(legs);
    for (int leg = 0; leg < legs; ++leg) {
        Snap fromSnap = snaps.get(leg);
        Snap toSnap = snaps.get(leg + 1);
        // enforce headings
        // at via-nodes and the target node the heading parameter is interpreted as the direction we want
        // to enforce for arriving (not starting) at this node. the starting direction is not enforced at
        // all for these points (unless using pass through). see this forum discussion:
        // https://discuss.graphhopper.com/t/meaning-of-heading-parameter-for-via-routing/5643/6
        double fromHeading = ((leg == 0) && (!headings.isEmpty())) ? headings.get(0) : Double.NaN;
        double toHeading = ((snaps.size() == headings.size()) && (!Double.isNaN(headings.get(leg + 1)))) ? headings.get(leg + 1) : Double.NaN;
        // enforce pass-through
        int incomingEdge = NO_EDGE;
        if (leg != 0) {
            // enforce straight start after via stop
            Path prevRoute = result.paths.get(leg - 1);
            if (prevRoute.getEdgeCount() > 0) {
                incomingEdge = prevRoute.getFinalEdge().getEdge();
            }
        }
        // enforce curbsides
        final String fromCurbside = (curbsides.isEmpty()) ? CURBSIDE_ANY : curbsides.get(leg);
        final String toCurbside = (curbsides.isEmpty()) ? CURBSIDE_ANY : curbsides.get(leg + 1);
        EdgeRestrictions edgeRestrictions = buildEdgeRestrictions(queryGraph, fromSnap, toSnap, fromHeading, toHeading, incomingEdge, passThrough, fromCurbside, toCurbside, directedEdgeFilter);
        edgeRestrictions.setSourceOutEdge(ignoreThrowOrAcceptImpossibleCurbsides(curbsides, edgeRestrictions.getSourceOutEdge(), leg, curbsideStrictness));
        edgeRestrictions.setTargetInEdge(ignoreThrowOrAcceptImpossibleCurbsides(curbsides, edgeRestrictions.getTargetInEdge(), leg + 1, curbsideStrictness));
        // calculate paths
        // PATH: Test should invoke the next CHPathCalculator.calcPaths(...) [step in execution path]
        List<Path> paths = pathCalculator.calcPaths(fromSnap.getClosestNode(), toSnap.getClosestNode(), edgeRestrictions);
        result.debug += pathCalculator.getDebugString();
        // for alternative routing we get multiple paths and add all of them (which is ok, because we do not allow
        // via-points for alternatives at the moment). otherwise we would have to return a list<list<path>> and find
        // a good method to decide how to combine the different legs
        for (int i = 0; i < paths.size(); i++) {
            Path path = paths.get(i);
            if (path.getTime() < 0) {
                throw new RuntimeException((("Time was negative " + path.getTime()) + " for index ") + i);
            }
            result.paths.add(path);
            result.debug += ", " + path.getDebugInfo();
        }
        result.visitedNodes += pathCalculator.getVisitedNodes();
        result.debug += ", visited nodes sum: " + result.visitedNodes;
    }
    return result;
}

@Override
public List<Path> calcPaths(int from, int to, EdgeRestrictions edgeRestrictions) {
    if (!edgeRestrictions.getUnfavoredEdges().isEmpty()) {
        throw new IllegalArgumentException("Using unfavored edges is currently not supported for CH");
    }
    EdgeToEdgeRoutingAlgorithm algo = createAlgo();
    // PATH: Test should invoke the next CHPathCalculator.calcPaths(...) [step in execution path]
    return calcPaths(from, to, edgeRestrictions, algo);
}

private List<Path> calcPaths(int from, int to, EdgeRestrictions edgeRestrictions, EdgeToEdgeRoutingAlgorithm algo) {
    StopWatch sw = new StopWatch().start();
    List<Path> paths;
    if ((edgeRestrictions.getSourceOutEdge() != ANY_EDGE) || (edgeRestrictions.getTargetInEdge() != ANY_EDGE)) {
        paths = Collections.singletonList(algo.calcPath(from, to, edgeRestrictions.getSourceOutEdge(), edgeRestrictions.getTargetInEdge()));
    } else {
        // PATH: Test should invoke the next AlternativeRouteCH.calcPaths(...) [step in execution path]
        paths = algo.calcPaths(from, to);
    }
    if (paths.isEmpty()) {
        throw new IllegalStateException((("Path list was empty for " + from) + " -> ") + to);
    }
    int maxVisitedNodes = algoOpts.getInt(MAX_VISITED_NODES, Integer.MAX_VALUE);
    if (algo.getVisitedNodes() >= maxVisitedNodes) {
        throw new MaximumNodesExceededException("No path found due to maximum nodes exceeded " + maxVisitedNodes, maxVisitedNodes);
    }
    visitedNodes = algo.getVisitedNodes();
    debug += (((", " + algo.getName()) + "-routing:") + sw.stop().getMillis()) + " ms";
    return paths;
}

@Override
public List<Path> calcPaths(int from, int to) {
    // PATH: Test should invoke the next AlternativeRouteCH.calcAlternatives(...) [step in execution path]
    List<AlternativeInfo> alts = calcAlternatives(from, to);
    if (alts.isEmpty()) {
        return Collections.singletonList(createEmptyPath());
    }
    List<Path> paths = new ArrayList<>(alts.size());
    for (AlternativeInfo a : alts) {
        paths.add(a.path);
    }
    return paths;
}

List<AlternativeInfo> calcAlternatives(final int s, final int t) {
    // First, do a regular bidirectional route search
    checkAlreadyRun();
    init(s, 0, t, 0);
    runAlgo();
    final Path bestPath = extractPath();
    if (!bestPath.isFound()) {
        return Collections.emptyList();
    }
    alternatives.add(new AlternativeInfo(bestPath, 0));
    final ArrayList<PotentialAlternativeInfo> potentialAlternativeInfos = new ArrayList<>();
    bestWeightMapFrom.forEach(((IntObjectPredicate<SPTEntry>) ((v, fromSPTEntry) -> {
        SPTEntry toSPTEntry = bestWeightMapTo.get(v);
        if (toSPTEntry == null)
            return true;

        if ((fromSPTEntry.getWeightOfVisitedPath() + toSPTEntry.getWeightOfVisitedPath()) > (bestPath.getWeight() * maxWeightFactor))
            return true;

        // This gives us a path s -> v -> t, but since we are using contraction hierarchies,
        // s -> v and v -> t need not be shortest paths. In fact, they can sometimes be pretty strange.
        // We still use this preliminary path to filter for shared path length with other alternatives,
        // so we don't have to work so much.
        Path preliminaryRoute = createPathExtractor().extract(fromSPTEntry, toSPTEntry, fromSPTEntry.getWeightOfVisitedPath() + toSPTEntry.getWeightOfVisitedPath());
        double preliminaryShare = calculateShare(preliminaryRoute);
        if (preliminaryShare > maxShareFactor) {
            return true;
        }
        PotentialAlternativeInfo potentialAlternativeInfo = new PotentialAlternativeInfo();
        potentialAlternativeInfo.v = v;
        potentialAlternativeInfo.weight = (2 * (fromSPTEntry.getWeightOfVisitedPath() + toSPTEntry.getWeightOfVisitedPath())) + preliminaryShare;
        potentialAlternativeInfos.add(potentialAlternativeInfo);
        return true;
    })));
    potentialAlternativeInfos.sort(Comparator.comparingDouble(o -> o.weight));
    for (PotentialAlternativeInfo potentialAlternativeInfo : potentialAlternativeInfos) {
        int v = potentialAlternativeInfo.v;
        // Okay, now we want the s -> v -> t shortest via-path, so we route s -> v and v -> t
        // and glue them together.
        DijkstraBidirectionCH svRouter = new DijkstraBidirectionCH(graph);
        svRouter.setPathExtractorSupplier(this::createPathExtractor);
        final Path svPath = svRouter.calcPath(s, v);
        extraVisitedNodes += svRouter.getVisitedNodes();
        DijkstraBidirectionCH vtRouter = new DijkstraBidirectionCH(graph);
        vtRouter.setPathExtractorSupplier(this::createPathExtractor);
        final Path vtPath = vtRouter.calcPath(v, t);
        Path path = concat(graph.getBaseGraph(), svPath, vtPath);
        extraVisitedNodes += vtRouter.getVisitedNodes();
        double sharedDistanceWithShortest = sharedDistanceWithShortest(path);
        double detourLength = path.getDistance() - sharedDistanceWithShortest;
        double directLength = bestPath.getDistance() - sharedDistanceWithShortest;
        if (detourLength > (directLength * maxWeightFactor)) {
            continue;
        }
        double share = calculateShare(path);
        if (share > maxShareFactor) {
            continue;
        }
        // This is the final test we need: Discard paths that are not "locally shortest" around v.
        // So move a couple of nodes to the left and right from v on our path,
        // route, and check if v is on the shortest path.
        final IntIndexedContainer svNodes = svPath.calcNodes();
        int vIndex = svNodes.size() - 1;
        if (!tTest(path, vIndex))
            continue;

        alternatives.add(new AlternativeInfo(path, share));
        if (alternatives.size() >= maxPaths)
            break;

    }
    return alternatives;
}

