        // ignore areas that aren't countries
        if (customArea.getProperties() == null)
            continue;

        String alpha2WithSubdivision = ((String) (customArea.getProperties().get(State.ISO_3166_2)));
        if (alpha2WithSubdivision == null)
            continue;

