}

public GHResponse route(GHRequest request) {
    try {
        checkNoLegacyParameters(request);
        checkAtLeastOnePoint(request);
        checkIfPointsAreInBoundsAndNotNull(request.getPoints());
        checkHeadings(request);
        checkPointHints(request);
        checkCurbsides(request);
        checkNoBlockArea(request);
        checkCustomModel(request);
        Solver solver = createSolver(request);
        solver.checkRequest();
        solver.init();
        if (ROUND_TRIP.equalsIgnoreCase(request.getAlgorithm())) {
            if (!(solver instanceof FlexSolver)) {
                throw new IllegalArgumentException("algorithm=round_trip only works with a flexible algorithm");
            }
            // PATH: Test should invoke the next Router.routeRoundTrip(...) [step in execution path]
            return routeRoundTrip(request, ((FlexSolver) (solver)));
        } else if (ALT_ROUTE.equalsIgnoreCase(request.getAlgorithm())) {
            return routeAlt(request, solver);
        } else {
            return routeVia(request, solver);
        }
    } catch (MultiplePointsNotFoundException ex) {
        GHResponse ghRsp = new GHResponse();
        for (IntCursor p : ex.getPointsNotFound()) {
            ghRsp.addError(new PointNotFoundException((("Cannot find point " + p.value) + ": ") + request.getPoints().get(p.value), p.value));
        }
        return ghRsp;
    } catch (IllegalArgumentException ex) {
        GHResponse ghRsp = new GHResponse();
        ghRsp.addError(ex);
        return ghRsp;
    }
}

protected GHResponse routeRoundTrip(GHRequest request, FlexSolver solver) {
    GHResponse ghRsp = new GHResponse();
    StopWatch sw = new StopWatch().start();
    double startHeading = (request.getHeadings().isEmpty()) ? Double.NaN : request.getHeadings().get(0);
    RoundTripRouting.Params params = new RoundTripRouting.Params(request.getHints(), startHeading, routerConfig.getMaxRoundTripRetries());
    List<Snap> snaps = RoundTripRouting.lookup(request.getPoints(), solver.createSnapFilter(), locationIndex, params);
    ghRsp.addDebugInfo(("idLookup:" + sw.stop().getSeconds()) + "s");
    // PATH: Test should invoke the next QueryGraph.create(...) [step in execution path]
    QueryGraph queryGraph = QueryGraph.create(graph, snaps);
    FlexiblePathCalculator pathCalculator = solver.createPathCalculator(queryGraph);
    RoundTripRouting.Result result = RoundTripRouting.calcPaths(snaps, pathCalculator);
    // we merge the different legs of the roundtrip into one response path
    // note that the waypoints are not just the snapped points of the snaps, as usual, because we do some kind of tweak
    // to avoid 'unnecessary tails' in the roundtrip algo
    ResponsePath responsePath = concatenatePaths(request, solver.weighting, queryGraph, result.paths, result.wayPoints);
    ghRsp.add(responsePath);
    ghRsp.getHints().putObject("visited_nodes.sum", result.visitedNodes);
    ghRsp.getHints().putObject("visited_nodes.average", ((float) (result.visitedNodes)) / (snaps.size() - 1));
    return ghRsp;
}

public static QueryGraph create(BaseGraph graph, List<Snap> snaps) {
    return new QueryGraph(graph, snaps);
}

private (BaseGraph graph, List<Snap> snaps) {
    baseGraph = graph;
    baseNodes = graph.getNodes();
    baseEdges = graph.getEdges();
    queryOverlay = QueryOverlayBuilder.build(graph, snaps);
    nodeAccess = new ExtendedNodeAccess(graph.getNodeAccess(), queryOverlay.getVirtualNodes(), baseNodes);
    turnCostStorage = baseGraph.getTurnCostStorage();
    // build data structures holding the virtual edges at all real/virtual nodes that are modified compared to the
    // mainGraph.
    final EdgeExplorer mainExplorer = baseGraph.createEdgeExplorer();
    // PATH: Test should invoke the next QueryGraph.buildVirtualEdgesAtRealNodes(...) [step in execution path]
    virtualEdgesAtRealNodes = buildVirtualEdgesAtRealNodes(mainExplorer);
    virtualEdgesAtVirtualNodes = buildVirtualEdgesAtVirtualNodes();
}

private IntObjectMap<List<EdgeIteratorState>> buildVirtualEdgesAtRealNodes(final EdgeExplorer mainExplorer) {
    final IntObjectMap<List<EdgeIteratorState>> virtualEdgesAtRealNodes = new GHIntObjectHashMap<>(queryOverlay.getEdgeChangesAtRealNodes().size());
    queryOverlay.getEdgeChangesAtRealNodes().forEach(new IntObjectProcedure<QueryOverlay.EdgeChanges>() {
        @Override
        public void apply(int node, QueryOverlay.EdgeChanges edgeChanges) {
            List<EdgeIteratorState> virtualEdges = new ArrayList<>(edgeChanges.getAdditionalEdges());
            EdgeIterator mainIter = mainExplorer.setBaseNode(node);
            while (mainIter.next()) {
                if (!edgeChanges.getRemovedEdges().contains(mainIter.getEdge())) {
                    virtualEdges.add(mainIter.detach(false));
                }
            } 
            virtualEdgesAtRealNodes.put(node, virtualEdges);
        }
    });
    return virtualEdgesAtRealNodes;
}
