    String curbsideStrictness = getCurbsideStrictness(request.getHints());
    if (passThrough) {
        throw new IllegalArgumentException(("Alternative paths and " + PASS_THROUGH) + " at the same time is currently not supported");
    }
    if (!request.getCurbsides().isEmpty()) {
        throw new IllegalArgumentException(("Alternative paths do not support the " + CURBSIDE) + " parameter yet");
    }
    ViaRouting.Result result = ViaRouting.calcPaths(request.getPoints(), queryGraph, snaps, directedEdgeFilter, pathCalculator, request.getCurbsides(), curbsideStrictness, request.getHeadings(), passThrough);
    if (result.paths.isEmpty()) {
