        profile.setVehicle("car");
        profile.setWeighting("fastest");

        try {
            java.lang.reflect.Field profilesField = GraphHopper.class.getDeclaredField("profilesByName");
            profilesField.setAccessible(true);
            Map<String, Profile> profilesMap = (Map<String, Profile>) profilesField.get(graphHopper);
            profilesMap.put("profile", profile);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Create a GHRequest that will trigger the alternative route path
        GHRequest request = new GHRequest();
        request.setAlgorithm("alternative_route");
        request.addPoint(new GHPoint(0, 0));
        request.addPoint(new GHPoint(0.01, 0.01));

        // Try to invoke the route method - this should trigger the call chain
        // We expect exceptions due to incomplete setup, but the chain should be attempted
        try {
            graphHopper.route(request);
        } catch (Exception e) {
            // Expected - we're not setting up a complete environment
        }
    }

