private void addRestrictionsToGraph() {
    if (turnCostStorage == null) {
        return;
    }
    StopWatch sw = StopWatch.started();
    // The OSM restriction format is explained here: https://wiki.openstreetmap.org/wiki/Relation:restriction
    List<Triple<ReaderRelation, RestrictionTopology, RestrictionMembers>> restrictionRelationsWithTopology = new ArrayList<>(restrictionRelations.size());
    for (ReaderRelation restrictionRelation : restrictionRelations) {
        try {
            // Build the topology of the OSM relation in the graph representation. This only needs to be done once for all
            // vehicle types (we also want to print warnings only once)
            // PATH: Test should invoke the next OSMRestrictionConverter.buildRestrictionTopologyForGraph(...) [step in execution path]
            restrictionRelationsWithTopology.add(OSMRestrictionConverter.buildRestrictionTopologyForGraph(baseGraph, restrictionRelation, restrictedWaysToEdgesMap::getEdges));
        } catch (OSMRestrictionException e) {
            warnOfRestriction(restrictionRelation, e);
        }
    }
    // It is important to set the restrictions for all parsers/encoded values at once to make
    // sure the resulting turn restrictions do not interfere.
    List<RestrictionSetter.Restriction> restrictions = new ArrayList<>();
    // For every restriction we set flags that indicate the validity for the different parsers
    List<BitSet> encBits = new ArrayList<>();
    for (Triple<ReaderRelation, RestrictionTopology, RestrictionMembers> r : restrictionRelationsWithTopology) {
        try {
            BitSet bits = new BitSet(osmParsers.getRestrictionTagParsers().size());
            RestrictionType restrictionType = null;
            for (int i = 0; i < osmParsers.getRestrictionTagParsers().size(); i++) {
                RestrictionTagParser restrictionTagParser = osmParsers.getRestrictionTagParsers().get(i);
                RestrictionTagParser.Result res = restrictionTagParser.parseRestrictionTags(r.first.getTags());
                // this relation is ignored by this restriction tag parser
                if (res == null) {
                    continue;
                }
                OSMRestrictionConverter.checkIfTopologyIsCompatibleWithRestriction(r.second, res.getRestriction());
                // so far we restrict ourselves to restriction relations that use the same type for all vehicles
                if ((restrictionType != null) && (res.getRestrictionType() != restrictionType)) {
                    throw new OSMRestrictionException("has different restriction type for different vehicles.");
                }
                restrictionType = res.getRestrictionType();
                bits.set(i);
            }
            if (bits.cardinality() > 0) {
                List<RestrictionSetter.Restriction> tmpRestrictions = OSMRestrictionConverter.buildRestrictionsForOSMRestriction(baseGraph, r.second, restrictionType);
                restrictions.addAll(tmpRestrictions);
                tmpRestrictions.forEach(__ -> encBits.add(RestrictionSetter.copyEncBits(bits)));
            }
        } catch (OSMRestrictionException e) {
            warnOfRestriction(r.first, e);
        }
    }
    restrictionSetter.setRestrictions(restrictions, encBits);
    LOGGER.info("Finished adding turn restrictions. total turn cost entries: {}, took: {}", Helper.nf(baseGraph.getTurnCostStorage().getTurnCostsCount()), sw.stop().getTimeString());
}

/**
 * OSM restriction relations specify turn restrictions between OSM ways (of course). This method rebuilds the
 * topology of such a relation in the graph representation, where the turn restrictions are specified in terms of edge/node IDs instead
 * of OSM IDs.
 *
 * @throws OSMRestrictionException
 * 		if the given relation is either not valid in some way and/or cannot be handled and
 * 		shall be ignored
 */
public static Triple<ReaderRelation, RestrictionTopology, RestrictionMembers> buildRestrictionTopologyForGraph(BaseGraph baseGraph, ReaderRelation relation, LongFunction<Iterator<IntCursor>> edgesByWay) throws OSMRestrictionException {
    if (!isTurnRestriction(relation)) {
        throw new IllegalArgumentException("expected a turn restriction: " + relation.getTags());
    }
    RestrictionMembers restrictionMembers = extractMembers(relation);
    if (!membersExist(restrictionMembers, edgesByWay, relation)) {
        throw OSMRestrictionException.withoutWarning();
    }
    // every OSM way might be split into *multiple* edges, so now we need to figure out which edges are the ones
    // that are actually part of the given relation
    WayToEdgeConverter wayToEdgeConverter = new WayToEdgeConverter(baseGraph, edgesByWay);
    if (restrictionMembers.isViaWay()) {
        // For now let's ignore all via-way restrictions with duplicate from/to/via-members
        // until we find cases where this is too strict.
        // PATH: Test should invoke the next OSMRestrictionConverter.containsDuplicateWays(...) [step in execution path]
        if (containsDuplicateWays(restrictionMembers)) {
            throw new OSMRestrictionException("contains duplicate from-/via-/to-members");
        }
        WayToEdgeConverter.EdgeResult res = wayToEdgeConverter.convertForViaWays(restrictionMembers.getFromWays(), restrictionMembers.getViaWays(), restrictionMembers.getToWays());
        return new Triple<>(relation, RestrictionTopology.way(res.getFromEdges(), res.getViaEdges(), res.getToEdges(), res.getNodes()), restrictionMembers);
    } else {
        int viaNode = relation.getTag("graphhopper:via_node", -1);
        if (viaNode < 0) {
            throw new IllegalStateException("For some reason we did not set graphhopper:via_node for this relation: " + relation.getId());
        }
        WayToEdgeConverter.NodeResult res = wayToEdgeConverter.convertForViaNode(restrictionMembers.getFromWays(), viaNode, restrictionMembers.getToWays());
        return new Triple<>(relation, RestrictionTopology.node(res.getFromEdges(), viaNode, res.getToEdges()), restrictionMembers);
    }
}

private static boolean containsDuplicateWays(RestrictionMembers restrictionMembers) {
    LongArrayList allWays = restrictionMembers.getAllWays();
    LongHashSet uniqueWays = new LongHashSet(allWays);
    // PATH: Test should invoke the next new LongHashSet(...) [step in execution path]
    return uniqueWays.size() != allWays.size();
}
