public GHResponse route(GHRequest request) {
    try {
        checkNoLegacyParameters(request);
        checkAtLeastOnePoint(request);
        checkIfPointsAreInBoundsAndNotNull(request.getPoints());
        checkHeadings(request);
        checkPointHints(request);
        checkCurbsides(request);
        checkNoBlockArea(request);
        checkCustomModel(request);
        Solver solver = createSolver(request);
        solver.checkRequest();
        solver.init();
        if (ROUND_TRIP.equalsIgnoreCase(request.getAlgorithm())) {
            if (!(solver instanceof FlexSolver)) {
                throw new IllegalArgumentException("algorithm=round_trip only works with a flexible algorithm");
            }
            return routeRoundTrip(request, ((FlexSolver) (solver)));
        } else if (ALT_ROUTE.equalsIgnoreCase(request.getAlgorithm())) {
            return routeAlt(request, solver);
        } else {
            // PATH: Test should invoke the next Router.routeVia(...) [step in execution path]
            return routeVia(request, solver);
        }
    } catch (MultiplePointsNotFoundException ex) {
        GHResponse ghRsp = new GHResponse();
        for (IntCursor p : ex.getPointsNotFound()) {
            ghRsp.addError(new PointNotFoundException((("Cannot find point " + p.value) + ": ") + request.getPoints().get(p.value), p.value));
        }
        return ghRsp;
    } catch (IllegalArgumentException ex) {
        GHResponse ghRsp = new GHResponse();
        ghRsp.addError(ex);
        return ghRsp;
    }
}

protected GHResponse routeVia(GHRequest request, Solver solver) {
    GHResponse ghRsp = new GHResponse();
    StopWatch sw = new StopWatch().start();
    DirectedEdgeFilter directedEdgeFilter = solver.createDirectedEdgeFilter();
    List<Snap> snaps = ViaRouting.lookup(encodingManager, request.getPoints(), solver.createSnapFilter(), locationIndex, request.getSnapPreventions(), request.getPointHints(), directedEdgeFilter, request.getHeadings());
    ghRsp.addDebugInfo(("idLookup:" + sw.stop().getSeconds()) + "s");
    // (base) query graph used to resolve headings, curbsides etc. this is not necessarily the same thing as
    // the (possibly implementation specific) query graph used by PathCalculator
    QueryGraph queryGraph = QueryGraph.create(graph, snaps);
    PathCalculator pathCalculator = solver.createPathCalculator(queryGraph);
    boolean passThrough = getPassThrough(request.getHints());
    String curbsideStrictness = getCurbsideStrictness(request.getHints());
    // PATH: Test should invoke the next ViaRouting.calcPaths(...) [step in execution path]
    ViaRouting.Result result = ViaRouting.calcPaths(request.getPoints(), queryGraph, snaps, directedEdgeFilter, pathCalculator, request.getCurbsides(), curbsideStrictness, request.getHeadings(), passThrough);
    if (request.getPoints().size() != (result.paths.size() + 1)) {
        throw new RuntimeException((("There should be exactly one more point than paths. points:" + request.getPoints().size()) + ", paths:") + result.paths.size());
    }
    // here each path represents one leg of the via-route and we merge them all together into one response path
    ResponsePath responsePath = concatenatePaths(request, solver.weighting, queryGraph, result.paths, getWaypoints(snaps));
    responsePath.addDebugInfo(result.debug);
    ghRsp.add(responsePath);
    ghRsp.getHints().putObject("visited_nodes.sum", result.visitedNodes);
    ghRsp.getHints().putObject("visited_nodes.average", ((float) (result.visitedNodes)) / (snaps.size() - 1));
    return ghRsp;
}

public static Result calcPaths(List<GHPoint> points, QueryGraph queryGraph, List<Snap> snaps, DirectedEdgeFilter directedEdgeFilter, PathCalculator pathCalculator, List<String> curbsides, String curbsideStrictness, List<Double> headings, boolean passThrough) {
    if ((!curbsides.isEmpty()) && (curbsides.size() != points.size())) {
        throw new IllegalArgumentException(("If you pass " + CURBSIDE) + ", you need to pass exactly one curbside for every point, empty curbsides will be ignored");
    }
    if ((!curbsides.isEmpty()) && (!headings.isEmpty())) {
        throw new IllegalArgumentException("You cannot use curbsides and headings or pass_through at the same time");
    }
    final int legs = snaps.size() - 1;
    Result result = new Result(legs);
    for (int leg = 0; leg < legs; ++leg) {
        Snap fromSnap = snaps.get(leg);
        Snap toSnap = snaps.get(leg + 1);
        // enforce headings
        // at via-nodes and the target node the heading parameter is interpreted as the direction we want
        // to enforce for arriving (not starting) at this node. the starting direction is not enforced at
        // all for these points (unless using pass through). see this forum discussion:
        // https://discuss.graphhopper.com/t/meaning-of-heading-parameter-for-via-routing/5643/6
        double fromHeading = ((leg == 0) && (!headings.isEmpty())) ? headings.get(0) : Double.NaN;
        double toHeading = ((snaps.size() == headings.size()) && (!Double.isNaN(headings.get(leg + 1)))) ? headings.get(leg + 1) : Double.NaN;
        // enforce pass-through
        int incomingEdge = NO_EDGE;
        if (leg != 0) {
            // enforce straight start after via stop
            Path prevRoute = result.paths.get(leg - 1);
            if (prevRoute.getEdgeCount() > 0) {
                incomingEdge = prevRoute.getFinalEdge().getEdge();
            }
        }
        // enforce curbsides
        final String fromCurbside = (curbsides.isEmpty()) ? CURBSIDE_ANY : curbsides.get(leg);
        final String toCurbside = (curbsides.isEmpty()) ? CURBSIDE_ANY : curbsides.get(leg + 1);
        EdgeRestrictions edgeRestrictions = buildEdgeRestrictions(queryGraph, fromSnap, toSnap, fromHeading, toHeading, incomingEdge, passThrough, fromCurbside, toCurbside, directedEdgeFilter);
        edgeRestrictions.setSourceOutEdge(ignoreThrowOrAcceptImpossibleCurbsides(curbsides, edgeRestrictions.getSourceOutEdge(), leg, curbsideStrictness));
        edgeRestrictions.setTargetInEdge(ignoreThrowOrAcceptImpossibleCurbsides(curbsides, edgeRestrictions.getTargetInEdge(), leg + 1, curbsideStrictness));
        // calculate paths
        // PATH: Test should invoke the next FlexiblePathCalculator.calcPaths(...) [step in execution path]
        List<Path> paths = pathCalculator.calcPaths(fromSnap.getClosestNode(), toSnap.getClosestNode(), edgeRestrictions);
        result.debug += pathCalculator.getDebugString();
        // for alternative routing we get multiple paths and add all of them (which is ok, because we do not allow
        // via-points for alternatives at the moment). otherwise we would have to return a list<list<path>> and find
        // a good method to decide how to combine the different legs
        for (int i = 0; i < paths.size(); i++) {
            Path path = paths.get(i);
            if (path.getTime() < 0) {
                throw new RuntimeException((("Time was negative " + path.getTime()) + " for index ") + i);
            }
            result.paths.add(path);
            result.debug += ", " + path.getDebugInfo();
        }
        result.visitedNodes += pathCalculator.getVisitedNodes();
        result.debug += ", visited nodes sum: " + result.visitedNodes;
    }
    return result;
}

