    @Test
    public void testRouteToIntArrayListIsEmpty() throws Exception {
        // Mock all required dependencies for Router constructor
        BaseGraph mockGraph = Mockito.mock(BaseGraph.class);
        EncodingManager mockEncodingManager = Mockito.mock(EncodingManager.class);
        LocationIndex mockLocationIndex = Mockito.mock(LocationIndex.class);
        Map<String, Profile> mockProfilesByName = new HashMap<>();
        PathDetailsBuilderFactory mockPathDetailsBuilderFactory = Mockito.mock(PathDetailsBuilderFactory.class);
        TranslationMap mockTranslationMap = Mockito.mock(TranslationMap.class);
        RouterConfig mockRouterConfig = Mockito.mock(RouterConfig.class);
        WeightingFactory mockWeightingFactory = Mockito.mock(WeightingFactory.class);
        Map<String, RoutingCHGraph> mockChGraphs = new HashMap<>();
        Map<String, LandmarkStorage> mockLandmarks = new HashMap<>();

        // Setup mock behavior for graph bounds check
        BBox mockBounds = Mockito.mock(BBox.class);
        Mockito.when(mockGraph.getBounds()).thenReturn(mockBounds);
        Mockito.when(mockBounds.contains(anyDouble(), anyDouble())).thenReturn(true);

        // Create Router instance
        Router router = new Router(
                mockGraph,
                mockEncodingManager,
                mockLocationIndex,
                mockProfilesByName,
                mockPathDetailsBuilderFactory,
                mockTranslationMap,
                mockRouterConfig,
                mockWeightingFactory,
                mockChGraphs,
                mockLandmarks
        );

        // Create GHRequest that will trigger the alternative route path
        GHRequest request = new GHRequest();
        request.setAlgorithm(Parameters.Algorithms.ALT_ROUTE);
        // Add at least two points for routing
        request.addPoint(new GHPoint(49.0, 11.0));
        request.addPoint(new GHPoint(49.1, 11.1));

        // Mock the solver creation to return a CHSolver that will eventually lead to AlternativeRouteEdgeCH
        CHSolver mockSolver = Mockito.mock(CHSolver.class);
        Mockito.when(mockSolver.createDirectedEdgeFilter()).thenReturn(Mockito.mock(DirectedEdgeFilter.class));
        Mockito.when(mockSolver.createSnapFilter()).thenReturn(Mockito.mock(EdgeFilter.class));

        // Mock the path calculator to be an AlternativeRouteEdgeCH
        AlternativeRouteEdgeCH mockPathCalculator = Mockito.mock(AlternativeRouteEdgeCH.class);
        Mockito.when(mockSolver.createPathCalculator(any(QueryGraph.class))).thenReturn(mockPathCalculator);

        // Mock the weighting
        Weighting mockWeighting = Mockito.mock(Weighting.class);
        Mockito.when(mockSolver.weighting).thenReturn(mockWeighting);

        // Mock the ViaRouting.lookup to return valid snaps
        List<Snap> mockSnaps = new ArrayList<>();
        Snap mockSnap1 = Mockito.mock(Snap.class);
        Snap mockSnap2 = Mockito.mock(Snap.class);
        Mockito.when(mockSnap1.getClosestNode()).thenReturn(1);
        Mockito.when(mockSnap2.getClosestNode()).thenReturn(2);
        mockSnaps.add(mockSnap1);
        mockSnaps.add(mockSnap2);

        // Mock the QueryGraph
        QueryGraph mockQueryGraph = Mockito.mock(QueryGraph.class);
        Mockito.when(QueryGraph.create(any(Graph.class), any(List.class))).thenReturn(mockQueryGraph);

        // Mock the path calculation to return a path that will trigger concat
        Path mockPath1 = Mockito.mock(Path.class);
        Path mockPath2 = Mockito.mock(Path.class);
        Mockito.when(mockPath1.getEdges()).thenReturn(IntArrayList.from(100));
        Mockito.when(mockPath2.getEdges()).thenReturn(IntArrayList.from(200, 300)); // Non-empty to avoid exception
        Mockito.when(mockPath1.isFound()).thenReturn(true);
        Mockito.when(mockPath2.isFound()).thenReturn(true);
        Mockito.when(mockPath1.getFromNode()).thenReturn(1);
        Mockito.when(mockPath2.getFromNode()).thenReturn(2);
        Mockito.when(mockPath2.getEndNode()).thenReturn(3);
        Mockito.when(mockPath1.getWeight()).thenReturn(100.0);
        Mockito.when(mockPath2.getWeight()).thenReturn(200.0);
        Mockito.when(mockPath1.getDistance()).thenReturn(1000.0);
        Mockito.when(mockPath2.getDistance()).thenReturn(2000.0);
        Mockito.when(mockPath1.getTime()).thenReturn(10000L);
        Mockito.when(mockPath2.getTime()).thenReturn(20000L);

        List<Path> mockPaths = Arrays.asList(mockPath1, mockPath2);
        Mockito.when(mockPathCalculator.calcPaths(anyInt(), anyInt(), any(EdgeRestrictions.class))).thenReturn(mockPaths);

        // Mock the graph edge iterator state for concat method
        EdgeIteratorState mockEdgeState = Mockito.mock(EdgeIteratorState.class);
        Mockito.when(mockGraph.getEdgeIteratorState(anyInt(), anyInt())).thenReturn(mockEdgeState);
        Mockito.when(mockEdgeState.getDistance()).thenReturn(500.0);
        Mockito.when(mockWeighting.calcEdgeWeight(any(EdgeIteratorState.class), anyBoolean())).thenReturn(50.0);
        Mockito.when(mockWeighting.calcEdgeMillis(any(EdgeIteratorState.class), anyBoolean())).thenReturn(5000L);

        // Use reflection to inject the mock solver into the router
        // Since we can't easily override the createSolver method, we'll create a minimal setup
        // that allows the route method to proceed through the alternative route branch
        // For simplicity, we'll directly call routeVia with our mock solver
        java.lang.reflect.Method routeViaMethod = Router.class.getDeclaredMethod("routeVia", GHRequest.class, Solver.class);
        routeViaMethod.setAccessible(true);

        // Execute the method
        routeViaMethod.invoke(router, request, mockSolver);
    }
}

