        for (int i = 0; i <= 10; i++) {
            firstEdgesByNode.add(i * 2);
        }

        // Use reflection to create PrepareContractionHierarchies instance
        // since constructor is private and we need to inject our prepared chStorage
        java.lang.reflect.Constructor<PrepareContractionHierarchies> constructor = 
            PrepareContractionHierarchies.class.getDeclaredConstructor(BaseGraph.class, CHConfig.class, CHStorage.class);
        constructor.setAccessible(true);

        PrepareContractionHierarchies pch = constructor.newInstance(mockGraph, mockChConfig, chStorage);

        // Use reflection to set up internal state to reach the target method
        // We need to initialize the graph and node contractor to avoid NPEs
        java.lang.reflect.Method initFromGraph = PrepareContractionHierarchies.class.getDeclaredMethod("initFromGraph");
        initFromGraph.setAccessible(true);
        initFromGraph.invoke(pch);

        // Call the entry point method
        pch.doWork();
    }
}

