@Override
public Path calcPath(int from, int to, int fromOutEdge, int toInEdge) // PATH: Test should invoke the next AStar.runAlgo(...) [step in execution path]
{
    if (((fromOutEdge != ANY_EDGE) || (toInEdge != ANY_EDGE)) && (!traversalMode.isEdgeBased())) {
        throw new IllegalArgumentException("Restricting the start/target edges is only possible for edge-based graph traversal");
    }
    this.fromOutEdge = fromOutEdge;
    this.toInEdge = toInEdge;
    checkAlreadyRun();
    setupFinishTime();
    this.to = to;
    if ((fromOutEdge == NO_EDGE) || (toInEdge == NO_EDGE)) {
        return extractPath();
    }
    weightApprox.setTo(to);
    double weightToGoal = weightApprox.approximate(from);
    if (Double.isInfinite(weightToGoal)) {
        return extractPath();
    }
    AStarEntry startEntry = new AStarEntry(EdgeIterator.NO_EDGE, from, 0 + weightToGoal, 0);
    fromHeap.add(startEntry);
    if (!traversalMode.isEdgeBased()) {
        fromMap.put(from, currEdge);
    }
    runAlgo();
    return extractPath();
}

private void runAlgo() {
    double currWeightToGoal;
    double estimationFullWeight;
    while (!fromHeap.isEmpty()) {
        currEdge = fromHeap.poll();
        if (currEdge.isDeleted()) {
            continue;
        }
        visitedNodes++;
        if ((isMaxVisitedNodesExceeded() || finished()) || isTimeoutExceeded()) {
            break;
        }
        int currNode = currEdge.adjNode;
        EdgeIterator iter = edgeExplorer.setBaseNode(currNode);
        while (iter.next()) {
            if ((!accept(iter, currEdge.edge)) || (((currEdge.edge == NO_EDGE) && (fromOutEdge != ANY_EDGE)) && (iter.getEdge() != fromOutEdge))) {
                continue;
            }
            double tmpWeight = GHUtility.calcWeightWithTurnWeight(weighting, iter, false, currEdge.edge) + currEdge.weightOfVisitedPath;
            if (Double.isInfinite(tmpWeight)) {
                continue;
            }
            int traversalId = traversalMode.createTraversalId(iter, false);
            AStarEntry ase = fromMap.get(traversalId);
            if ((ase == null) || (ase.weightOfVisitedPath > tmpWeight)) {
                int neighborNode = iter.getAdjNode();
                // PATH: Test should invoke the next LMApproximator.approximate(...) [step in execution path]
                currWeightToGoal = weightApprox.approximate(neighborNode);
                if (Double.isInfinite(currWeightToGoal)) {
                    continue;
                }
                estimationFullWeight = tmpWeight + currWeightToGoal;
                if (ase == null) {
                    ase = new AStarEntry(iter.getEdge(), neighborNode, estimationFullWeight, tmpWeight, currEdge);
                    fromMap.put(traversalId, ase);
                } else {
                    // assert (ase.weight > 0.9999999 * estimationFullWeight) : "Inconsistent distance estimate. It is expected weight >= estimationFullWeight but was "
                    // + ase.weight + " < " + estimationFullWeight + " (" + ase.weight / estimationFullWeight + "), and weightOfVisitedPath:"
                    // + ase.weightOfVisitedPath + " vs. alreadyVisitedWeight:" + alreadyVisitedWeight + " (" + ase.weightOfVisitedPath / alreadyVisitedWeight + ")";
                    ase.setDeleted();
                    ase = new AStarEntry(iter.getEdge(), neighborNode, estimationFullWeight, tmpWeight, currEdge);
                    fromMap.put(traversalId, ase);
                }
                fromHeap.add(ase);
                updateBestPath(iter, ase, traversalId);
            }
        } 
    } 
}

@Override
public double approximate(final int v) {
    if (((!recalculateActiveLandmarks) && fallback) || lms.isEmpty()) {
        return fallBackApproximation.approximate(v);
    }
    if (v >= maxBaseNodes) {
        // handle virtual node
        return 0;
    }
    if (v == towerNodeNextToT) {
        return 0;
    }
    // select better active landmarks, LATER: use 'success' statistics about last active landmark
    // we have to update the priority queues and the maps if done in the middle of the search http://cstheory.stackexchange.com/q/36355/13229
    if (recalculateActiveLandmarks) {
        recalculateActiveLandmarks = false;
        // PATH: Test should invoke the next LandmarkStorage.chooseActiveLandmarks(...) [step in execution path]
        if (lms.chooseActiveLandmarks(v, towerNodeNextToT, activeLandmarkIndices, reverse)) {
            for (int i = 0; i < activeLandmarkIndices.length; i++) {
                weightsFromActiveLandmarksToT[i] = lms.getFromWeight(activeLandmarkIndices[i], towerNodeNextToT);
                weightsFromTToActiveLandmarks[i] = lms.getToWeight(activeLandmarkIndices[i], towerNodeNextToT);
            }
        } else {
            // note: fallback==true means forever true!
            fallback = true;
            return fallBackApproximation.approximate(v);
        }
    }
    double lmApproximation = Math.max(0.0, (getRemainingWeightUnderestimationUpToTowerNode(v) - weightFromTToTowerNode) * epsilon);
    // Since both the LM and the beeline approximations underestimate the real remaining weight the larger one is
    // more accurate. For example when the speed is reduced for all roads the beeline approximation adjusts automatically
    // to the reduced global maximum speed, while the LM approximation becomes worse.
    return Math.max(lmApproximation, beelineApproximation.approximate(v));
}

// From all available landmarks pick just a few active ones
boolean chooseActiveLandmarks(int fromNode, int toNode, int[] activeLandmarkIndices, boolean reverse) {
    if ((fromNode < 0) || (toNode < 0)) {
        throw new IllegalStateException(((("from " + fromNode) + " and to ") + toNode) + " nodes have to be 0 or positive to init landmarks");
    }
    int subnetworkFrom = subnetworkStorage.getSubnetwork(fromNode);
    int subnetworkTo = subnetworkStorage.getSubnetwork(toNode);
    if ((subnetworkFrom <= UNCLEAR_SUBNETWORK) || (subnetworkTo <= UNCLEAR_SUBNETWORK)) {
        return false;
    }
    if (subnetworkFrom != subnetworkTo) {
        throw new ConnectionNotFoundException((("Connection between locations not found. Different subnetworks " + subnetworkFrom) + " vs. ") + subnetworkTo, new HashMap<>());
    }
    // See the similar formula in LMApproximator.approximateForLandmark
    List<Map.Entry<Integer, Integer>> list = new ArrayList<>(landmarks);
    for (int lmIndex = 0; lmIndex < landmarks; lmIndex++) {
        int fromWeight = getFromWeight(lmIndex, toNode) - getFromWeight(lmIndex, fromNode);
        int toWeight = getToWeight(lmIndex, fromNode) - getToWeight(lmIndex, toNode);
        list.add(new MapEntry<>(reverse ? Math.max(-fromWeight, -toWeight) : Math.max(fromWeight, toWeight), lmIndex));
    }
    Collections.sort(list, SORT_BY_WEIGHT);
    if (activeLandmarkIndices[0] >= 0) // PATH: Test should invoke the next new IntHashSet(...) [step in execution path]
    {
        IntHashSet set = new IntHashSet(activeLandmarkIndices.length);
        set.addAll(activeLandmarkIndices);
        int existingLandmarkCounter = 0;
        final int COUNT = Math.min(activeLandmarkIndices.length - 2, 2);
        for (int i = 0; i < activeLandmarkIndices.length; i++) {
            if (i >= ((activeLandmarkIndices.length - COUNT) + existingLandmarkCounter)) {
                // keep at least two of the previous landmarks (pick the best)
                break;
            } else {
                activeLandmarkIndices[i] = list.get(i).getValue();
                if (set.contains(activeLandmarkIndices[i])) {
                    existingLandmarkCounter++;
                }
            }
        }
    } else {
        for (int i = 0; i < activeLandmarkIndices.length; i++) {
            activeLandmarkIndices[i] = list.get(i).getValue();
        }
    }
    return true;
}
