protected void prepareImport() {
    Map<String, PMap> encodedValuesWithProps = parseEncodedValueString(encodedValuesString);
    NameValidator nameValidator = s -> importRegistry.createImportUnit(s) != null;
    Set<String> missing = new LinkedHashSet<>();
    profilesByName.values().forEach(profile -> CustomModelParser.findVariablesForEncodedValuesString(profile.getCustomModel(), nameValidator, s -> "").forEach(var -> {
        if (!encodedValuesWithProps.containsKey(var))
            missing.add(var);

